#!/usr/bin/env python3
"""NEW exact infinity input for the fixed original exceptional Phi=0 PB pair.
Read two saved exact QQ inputs; no previous six-by-six determinants,
QQ resultant, or old modular resultant is recomputed.
Reverse lambda in the original fixed 57x57 Sylvester matrix, using its
already-paid row degrees 26 (31 rows), 50 (26 rows).  Actual QQ left
kernels, unipotent row replacements, and division by the single variable
s certify the infinity order.  All polynomial divisions are multiplied back.
120 seconds / 1 GiB.  This is not a whole-branch exclusion.
"""
import os,sys,time,json,hashlib,base64,zlib,signal,resource
from math import gcd,lcm
from flint import fmpq,fmpq_poly,fmpq_mat,fmpq_mpoly_ctx,nmod_poly
signal.alarm(120)
resource.setrlimit(resource.RLIMIT_AS,(1024**3,1024**3))
began=time.perf_counter()
def say(stage,**kw):
 kw.update(stage=stage,seconds=time.perf_counter()-began)
 print(json.dumps(kw),flush=True)
ctx=fmpq_mpoly_ctx.get(("rho","lam"),"lex")
def phash(pp):
 return hashlib.sha256(str(sorted(pp.to_dict().items())).encode()).hexdigest()
def decode(data,sha,expected_sha,degree,terms):
 raw=zlib.decompress(base64.b64decode(data))
 assert hashlib.sha256(raw).hexdigest()==sha
 src=json.loads(raw);assert src["variables"]==["rho","lam"]
 pp=ctx.from_dict({(int(i),int(j)):fmpq(v) for i,j,v in src["terms"]})
 assert phash(pp)==expected_sha
 assert list(map(int,pp.degrees()))==degree and len(pp.to_dict())==terms
 return pp
F=decode("","7c4ecb78633f9539f26e6e989bb883ea78b1ae4919399a7d6358725b0ef5bae8",
 "9057238c5d37c8cd9f62f3f512dcff1f6d2e385cd6c0e39250a571713f0aaac7",[26,26],729)
G=decode("","f23a696f966d39ee022ffe3060946cc0b0555f06b2dfbbecb07fb23bcac86ffa",
 "3d850765f6c9338aa8f79af2b5889582cf8d4f45fd81ad90f4743fb5bebd5f6c",[31,50],1632)
def primitive_integer(pp):
 den=1
 for cc in pp.to_dict().values():den=lcm(den,int(fmpq(cc).denominator))
 vals={ex:fmpq(cc)*den for ex,cc in pp.to_dict().items()}
 content=0
 for cc in vals.values():
  assert cc.denominator==1
  content=gcd(content,abs(int(cc.numerator)))
 assert content
 out=ctx.from_dict({ex:fmpq(int(cc.numerator)//content) for ex,cc in vals.items()})
 scalar=fmpq(den,content)
 if out.coefficient(0)<0:out=-out;scalar=-scalar
 assert out==scalar*pp
 return out,scalar
F,fs=primitive_integer(F);G,gs=primitive_integer(G)
assert fs==1 and gs==fmpq(63398675155279049532452634624)
assert phash(G)=="dd8d70268ebe0ba9d519f336f1ac88a32c5067753d9c54d6143c87ed3d5ff24d"
# The already executed, fixed original modular determinant gives the upper
# bound on the characteristic-zero infinity valuation.  Its exact saved
# coefficients are decoded, hashed, and reconstructed, not recomputed.
rawmod=zlib.decompress(base64.b64decode(""))
assert hashlib.sha256(rawmod).hexdigest()=="e2cc0cd7d4542509e406c2324516f2f7c8d96e9d250f50b8d82c75f2447d6b10"
modcoef=json.loads(rawmod);Rbar=nmod_poly(modcoef,1009)
assert hashlib.sha256(str(Rbar).encode()).hexdigest()=="f4505a726a6c2691ac52b92ec424160f7cc748d6a9b17751ce8b2f9f3f0eaa85"
assert Rbar.degree()==2033
m,n,N=26,31,57
upper,target,precision=2106,73,74
ss=fmpq_poly([0,1]);zero=fmpq_poly([])
def reverse_coefficients(pp,rhodegree,lambdabound):
 out=[]
 for i in range(rhodegree+1):
  co=[fmpq(0)]*(lambdabound+1)
  for ex,v in pp.to_dict().items():
   if int(ex[0])==i:
    assert 0<=int(ex[1])<=lambdabound
    co[lambdabound-int(ex[1])]=v
  pp1=fmpq_poly(co)
  for j in range(lambdabound+1):
   assert pp1[lambdabound-j]==pp.to_dict().get((i,j),0)
  out.append(pp1)
 return out
fc,gc=reverse_coefficients(F,m,26),reverse_coefficients(G,n,50)
matrix=[[zero]*shift+fc+[zero]*(n-1-shift) for shift in range(n)]
matrix+=[[zero]*shift+gc+[zero]*(m-1-shift) for shift in range(m)]
assert len(matrix)==N and all(len(row)==N for row in matrix)
assert 31*26+26*50==upper
say("new_original_fixed_57_infinity_matrix",
 fixedRhoDegrees=[m,n],dimension=N,originalLambdaUpper=upper,
 originalRowDegrees=[26]*31+[50]*26,initialPrecision=precision,
 targetInfinityValuation=target,savedFullModDegree=2033,
 reverseEachOriginalCoefficientReturned=True,
 noOldCofactorOrResultantReplay=True)
stats=dict(kernel_equations=0,polynomial_division_products=0,
 precision_reduction_products=0,unipotent_square_zero_checks=0)
extracted=0;rounds=[]
def digest_matrix(mat):
 hh=hashlib.sha256()
 for row in mat:
  for p in row:
   hh.update(str(p).encode());hh.update(b"\n")
 return hh.hexdigest()
while extracted<target:
 const=fmpq_mat([[p[0] for p in row] for row in matrix])
 trans=fmpq_mat([[const[j,i] for j in range(N)] for i in range(N)])
 reduced,rank=trans.rref();rank=int(rank)
 piv=[]
 for i in range(rank):
  jj=next(j for j in range(N) if reduced[i,j]!=0)
  assert reduced[i,jj]==1
  assert all(reduced[k,jj]==(1 if k==i else 0) for k in range(N))
  piv.append(jj)
 assert piv==sorted(piv)
 free=[j for j in range(N) if j not in piv]
 assert len(free)==N-rank
 if not free:
  say("new_exact_QQ_infinity_full_rank_before_target",
      extracted=extracted,currentPrecision=precision,
      QQDegreeExactly=upper-extracted,modDegree=2033,
      modLeadingUnitPaid=(upper-extracted==2033),
      noWholeBranchExclusion=True,statistics=stats)
  break
 bases=[]
 for j in free:
  v=[fmpq(0)]*N;v[j]=1
  for i,pivcol in enumerate(piv):v[pivcol]=-reduced[i,j]
  assert all(v[k]==(1 if k==j else 0) for k in free)
  for col in range(N):
   assert sum((v[k]*const[k,col] for k in range(N)),fmpq(0))==0
   stats["kernel_equations"]+=1
  bases.append(v)
 # P=I+N0: replace each free-index row j by v_j times the OLD matrix.
 # N0 has nonzero rows only at free indices and zero free-index columns,
 # hence N0^2=0 and det P=1 without inverting a parameter.
 for j,v in zip(free,bases):
  for k in free:assert v[k]-(1 if j==k else 0)==0
 stats["unipotent_square_zero_checks"]+=1
 newrows=[]
 for v in bases:
  row=[]
  for col in range(N):
   value=sum((matrix[k][col]*v[k] for k in range(N) if v[k]),zero)
   assert value[0]==0
   divided=fmpq_poly([value[d] for d in range(1,int(value.degree())+1)]) if value else zero
   assert divided*ss==value
   stats["polynomial_division_products"]+=1
   row.append(divided)
  newrows.append(row)
 for j,row in zip(free,newrows):matrix[j]=row
 old_precision=precision;precision-=1
 assert precision>=1
 modulus=ss**precision
 for i in range(N):
  for j in range(N):
   value=matrix[i][j];degree=int(value.degree())
   rem=fmpq_poly([value[k] for k in range(min(precision,degree+1))])
   quotient=(fmpq_poly([value[k] for k in range(precision,degree+1)])
             if degree>=precision else zero)
   assert quotient*modulus+rem==value
   stats["precision_reduction_products"]+=1
   matrix[i][j]=rem
 extracted+=len(free)
 # Initial det agrees modulo s^74.  At each stage E+precision stays >=74:
 # E increases by at least 1; precision decreases by exactly 1.
 assert extracted+precision>=target+1
 assert extracted<=target
 trace=dict(round=len(rounds)+1,constantRank=rank,
            actualKernelDimension=len(free),selectedRows=free,
            extractedTotal=extracted,previousPrecision=old_precision,
            newPrecision=precision,
            kernelSha256=hashlib.sha256(str(bases).encode()).hexdigest(),
            reducedMatrixSha256=digest_matrix(matrix))
 rounds.append(trace)
 say("new_QQ_infinity_unipotent_kernel_extraction",
     **trace,statistics=dict(stats),
     everyKernelEquationAndDivisionReturned=True)
paid=(extracted==target)
say("complete_new_original_exceptional_PB_infinity_input",
 exactInfinityValuation=(target if paid else extracted),
 exactQQLambdaDegree=(2033 if paid else upper-extracted),
 originalPrimitiveResultantIntegral=True,
 leadingCoefficient1009UnitPaid=paid,
 originalTwoPolynomialQQGcdOnePreviouslyPaid=True,
 distinctOrderedWeightPointUpperBound=(2033 if paid else upper-extracted),
 fixedOriginalSylvesterPreservesAllRhoHeadZeroFibers=True,
 noOldProjectionReplay=True,statistics=stats,rounds=rounds,
 entireExceptionalBranchExcluded=False,ordinaryISPClaim=False)
